<template><div class="mvp-coach-state"><div v-if="!hideReply&&(replyState||state)==='thinking'" class="mvp-coach-thinking" role="status">AI Coach is preparing your reply<span aria-hidden="true">•••</span></div><section v-if="['plan-preview','plan-active'].includes(state)" class="mvp-dynamic-preview"><sf-badge :tone="state==='plan-active'?'success':'neutral'">{{ state==='plan-active'?'Plan activated':'Dynamic Plan preview' }}</sf-badge><h3>Your next step, with a little structure.</h3><p v-if="state==='plan-active'">Your plan is ready. View your upcoming sessions and start when you’re ready.</p><template v-else><p>Preview your training direction with AI Coach. Activate your saved Dynamic Plan when you’re ready to follow it.</p><ul><li>Bring your training goal into focus</li><li>Keep your upcoming sessions together</li><li>Use your saved plan as a starting point</li></ul></template><sf-button @click="$emit('action',state==='plan-active'?'plan':'activate-plan')">{{ state==='plan-active'?'View Plan':'Activate Plan' }}</sf-button><small v-if="state!=='plan-active'">{{ member.active?'Included with Premium. Activation uses no conversation allowance.':'Premium is required to activate. Discussing a plan uses your conversation allowance.' }}</small></section></div></template>
<script>import {SfBadge,SfButton} from '@/design-system';export default{components:{SfBadge,SfButton},props:{hideReply:Boolean,state:String,replyState:String,member:Object}}</script>
<style scoped>.mvp-coach-state{display:grid;gap:12px;margin-bottom:18px}.mvp-coach-thinking{padding:20px;border-radius:18px;background:var(--sf-content-surface);font-size:13px;line-height:1.6}.mvp-coach-thinking>span{display:block;letter-spacing:5px;color:var(--sf-action);margin-top:8px}.mvp-dynamic-preview{padding:18px 16px;background:var(--sf-content-surface);border:1px solid var(--sf-content-edge);border-radius:20px}.mvp-dynamic-preview h3{font-size:19px;line-height:26px;margin:14px 0 9px;letter-spacing:-.3px}.mvp-dynamic-preview p,.mvp-dynamic-preview li{font-size:13px;line-height:21px;color:var(--sf-text-secondary)}.mvp-dynamic-preview ul{padding-left:18px;margin:12px 0 18px}.mvp-dynamic-preview small{display:block;font-size:11px;line-height:18px;margin-top:10px;color:var(--sf-text-secondary)}.mvp-coach-state:empty{display:none}</style>
